import{c as t,Q as r,j as a,m as o}from"./chunks/framework.BXc4yaFE.js";const h=JSON.parse('{"title":"From Agent Loops to Structured Graphs: A Scheduler-Theoretic Framework for LLM Agent Execution","description":"","frontmatter":{"url":"https://arxiv.org/abs/2604.11378","title":"From Agent Loops to Structured Graphs: A Scheduler-Theoretic Framework for LLM Agent Execution","archived_date":"2026-06-24T00:00:00.000Z","arxiv_id":2604.11378,"authors":["Hu Wei"],"domains":["cs.AI"],"html":"https://arxiv.org/html/2604.11378v1","pdf_path":"pdfs/2604.11378.pdf","published_date":"2026-04-13T00:00:00.000Z"},"headers":[],"relativePath":"research/papers/2026-04-13-agent-loops-to-structured-graphs-scheduler-2604-11378.md","filePath":"research/papers/2026-04-13-agent-loops-to-structured-graphs-scheduler-2604-11378.md","lastUpdated":1785909234000}'),i={name:"research/papers/2026-04-13-agent-loops-to-structured-graphs-scheduler-2604-11378.md"};function n(s,e,l,c,p,d){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="from-agent-loops-to-structured-graphs-a-scheduler-theoretic-framework-for-llm-agent-execution" tabindex="-1">From Agent Loops to Structured Graphs: A Scheduler-Theoretic Framework for LLM Agent Execution <a class="header-anchor" href="#from-agent-loops-to-structured-graphs-a-scheduler-theoretic-framework-for-llm-agent-execution" aria-label="Permalink to &quot;From Agent Loops to Structured Graphs: A Scheduler-Theoretic Framework for LLM Agent Execution&quot;">​</a></h1><p><strong>Authors</strong>: Hu Wei <strong>Published</strong>: April 13, 2026 <strong>Source</strong>: <a href="https://arxiv.org/abs/2604.11378" target="_blank" rel="noreferrer">https://arxiv.org/abs/2604.11378</a> · <a href="https://arxiv.org/html/2604.11378v1" target="_blank" rel="noreferrer">HTML</a><strong>arXiv ID</strong>: 2604.11378 <strong>Categories</strong>: cs.AI <strong>PDF</strong>: <a href="https://arxiv.org/abs/2604.11378" target="_blank" rel="noreferrer">research/papers/pdfs/2604.11378.pdf</a> (50 pp, full text archived)</p><hr><h2 id="abstract-quoted" tabindex="-1">Abstract (quoted) <a class="header-anchor" href="#abstract-quoted" aria-label="Permalink to &quot;Abstract (quoted)&quot;">​</a></h2><blockquote><p>The dominant paradigm for building LLM based agents is the Agent Loop, an iterative cycle where a single language model decides what to do next by reading an ever growing context window. This paradigm has three structural weaknesses: implicit dependencies between steps, unbounded recovery loops, and mutable execution history that complicates debugging. We characterize the Agent Loop as a single ready unit scheduler: at any moment, at most one executable unit is active, and the choice of which unit to activate comes from opaque LLM inference rather than an inspectable policy. This perspective places Agent Loops and graph based execution engines on a single semantic continuum. We propose SGH, Structured Graph Harness, which lifts control flow from implicit context into an explicit static DAG. SGH makes three commitments: execution plans are immutable within a plan version, planning execution and recovery are separated into three layers, and recovery follows a strict escalation protocol. These choices trade some expressiveness for controllability, verifiability, and implementability. Our contributions are fourfold: a scheduler unified framework that applies classical scheduling theory to LLM agent execution and identifies challenges introduced by non deterministic LLM nodes; a trade off analysis of controllability, expressiveness, and implementability across 70 surveyed systems; a formal specification including a node state machine with termination and soundness guarantees; and an attributable experimental framework with a seven group design for future validation. This is a position paper and design proposal. We provide a theoretical framework, design analysis, and experimental protocol, not a production implementation or empirical results.</p></blockquote><hr><h2 id="結構化摘要" tabindex="-1">結構化摘要 <a class="header-anchor" href="#結構化摘要" aria-label="Permalink to &quot;結構化摘要&quot;">​</a></h2><h3 id="核心貢獻" tabindex="-1">核心貢獻 <a class="header-anchor" href="#核心貢獻" aria-label="Permalink to &quot;核心貢獻&quot;">​</a></h3><ul><li>提出 <strong>scheduler-unified framework</strong>：把 classical scheduling theory 套到 LLM agent 執行，並指出 non-deterministic LLM node 帶來的新挑戰。</li><li>將 <strong>Agent Loop</strong> 重新刻畫為 <em>single ready-unit scheduler</em>——任一時刻至多一個 executable unit 為 active，且「下一步選誰」由 opaque LLM inference 而非可檢視的 policy 決定；由此把 Agent Loop 與 graph-based execution engine 放在同一 semantic continuum 上。</li><li>提出 <strong>SGH (Structured Graph Harness)</strong>：把 control flow 從 implicit context 提升為 explicit static DAG，三項 commitment——plan 在版本內 immutable、planning / execution / recovery 三層分離、recovery 走 strict escalation protocol。</li><li>給出 <strong>formal specification</strong>：含 node state machine，附 termination 與 soundness guarantee。</li><li>設計 <strong>attributable experimental framework</strong>：seven-group design，供後續 validation。</li></ul><h3 id="關鍵結果" tabindex="-1">關鍵結果 <a class="header-anchor" href="#關鍵結果" aria-label="Permalink to &quot;關鍵結果&quot;">​</a></h3><ul><li>屬 position paper / design proposal，<strong>無 empirical results</strong>（作者明示）。</li><li>量化面僅有：橫跨 <strong>70 個 surveyed systems</strong> 的 controllability / expressiveness / implementability trade-off 分析。</li><li>方法層發現：明確指出 Agent Loop 三大結構弱點——implicit dependencies between steps、unbounded recovery loops、mutable execution history（debug 困難）；SGH 以 expressiveness 換取 controllability / verifiability / implementability。</li></ul><h3 id="限制" tabindex="-1">限制 <a class="header-anchor" href="#限制" aria-label="Permalink to &quot;限制&quot;">​</a></h3><ul><li>作者自述：<strong>This is a position paper and design proposal</strong>，提供 theoretical framework / design analysis / experimental protocol，<strong>非 production implementation、亦無 empirical results</strong>。</li><li>判斷弱點：seven-group experimental design 僅為 protocol，未跑；SGH 的 static DAG 假設可能不適合高度 open-ended、需動態重規劃的任務（immutable plan 與真實 agent 探索性需求之間的張力未經實證檢驗）；single-author position paper，trade-off 結論依賴 survey 詮釋而非對照實驗。</li></ul><hr><h2 id="workspace-關聯-評估-非既成結論" tabindex="-1">Workspace 關聯（評估，非既成結論） <a class="header-anchor" href="#workspace-關聯-評估-非既成結論" aria-label="Permalink to &quot;Workspace 關聯（評估，非既成結論）&quot;">​</a></h2><ul><li>本論文把 Agent Loop 形式化為「single ready-unit scheduler + opaque policy」，與本 workspace 的 <strong>The Loop</strong>（OBSERVE→…→RECORD 六階段）形成對照：The Loop 已把「下一步選誰」用可機械驗證的成功條件外顯化，正是 SGH 主張的「lift control flow into inspectable policy」方向。⚠️ 落地門檻：本 repo 的階段是 advisory prompt 規則，非 static DAG runtime，無 termination/soundness guarantee。</li><li>SGH 的 <em>planning / execution / recovery 三層分離</em> 對應 <code>core.md §PROPOSE 委派</code>（原 <code>subagent-strategy.md</code>）的 parent↔child 拓撲與 <code>error-handling.md</code> 的控制語義；可作為「dynamic workflow 三失敗模式（laziness / self-preferential bias / goal drift）」的理論補強。⚠️ 論文無實作，無法直接驗證能否抑制 goal drift。 〔v5.1：所引 workspace 細則已退役 → 見 <code>INDEX.md</code> §v5.1 規則退役對照〕</li><li><em>strict escalation protocol</em> 概念與 <code>self-escalate</code> agent（≥3 次同問失敗 → escalate 非 retry）同源，可借其 node state machine 形式化現有升級鏈。⚠️ 需自行把 prompt 級規則映射到狀態機，非現成模組。</li><li><em>immutable plan version</em> 與本 workspace 「commit 原子性 / 不可逆 gate」哲學一致；但 ⚠️ 對 off-rails 探索性任務，immutable DAG 可能與 IDENTIFY 階段的 open-question 動態調整衝突，採用前須評估任務是否真為 static-planable。</li></ul>',16)])])}const m=t(i,[["render",n]]);export{h as __pageData,m as default};
